/**
 * Small real media files for audio/video tests, made with ffmpeg from two
 * sine sources merged into stereo (`sine=frequency=440` and `880`, 48 kHz,
 * `amerge`) plus a 32 × 24 red video where noted. Every clip is 2 seconds:
 * a 440 Hz tone on the left channel and 880 Hz on the right, so tests can
 * check the content and channel order of the converted audio, not just its size.
 * Stored as base64 so they survive any file transfer unchanged.
 */

const b64 = (s: string) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));

/** VP8 video + Opus stereo, 2 s, 48 kHz. */
export const clipWebm = b64(
  '',
);
/** H.264 video + AAC-LC stereo, 2 s, 48 kHz. */
export const clipMp4 = b64(
  '',
);
/** clip.webm remuxed as Matroska. */
export const clipMkv = b64(
  '',
);
/** clip.mp4 remuxed as QuickTime. */
export const clipMov = b64(
  '',
);
/** VP8 video only, no sound track. */
export const silentWebm = b64(
  '',
);
/** MP3 64 kbps stereo with an ID3 tag, 48 kHz. */
export const toneMp3 = b64(
  '',
);
/** Ogg Vorbis stereo, 48 kHz. */
export const toneOgg = b64(
  '',
);
/** FLAC stereo, 16 kHz. */
export const toneFlac = b64(
  '',
);
/** AAC-LC in M4A, stereo, 48 kHz. */
export const toneM4a = b64(
  '',
);
/** raw ADTS AAC. */
export const toneAac = b64(
  '',
);

/** Left and right tone frequencies in every clip. */
export const TONES = { left: 440, right: 880 } as const;
export const CLIP_SECONDS = 2;
